<?php require 'config/bootstrap.php';auth();if(me()['role']!=='penjual'){flash('Akun harus role penjual','error');header('Location: profile.php');exit;}$id=(int)($_GET['id']??0);$p=['nama_produk'=>'','deskripsi_produk'=>'','status_produk'=>'ready_stock','whatsapp'=>'','gambar_produk'=>null];if($id){$s=$pdo->prepare('SELECT * FROM produk WHERE id=? AND user_id=?');$s->execute([$id,me()['id']]);$p=$s->fetch();if(!$p)exit('Produk bukan milik Anda');}headpage('Form produk');?><div class="panel p-4 mx-auto" style="max-width:750px"><h1><?=$id?'Edit':'Tambah'?> Produk</h1><form method="post" enctype="multipart/form-data" action="<?=$id?'actions/product-update.php':'actions/product-create.php'?>"><input type="hidden" name="csrf" value="<?=e(token())?>"><?php if($id):?><input type="hidden" name="id" value="<?=$id?>"><?php endif;?><label>Nama produk</label><input class="form-control mb-3" name="nama_produk" value="<?=e($p['nama_produk'])?>" required><label>Deskripsi</label><textarea class="form-control mb-3" name="deskripsi_produk" required rows="5"><?=e($p['deskripsi_produk'])?></textarea><label>Status</label><select class="form-select mb-3" name="status_produk"><?php foreach(['ready_stock'=>'Ready Stock','pre_order'=>'Pre Order','sold_out'=>'Sold Out'] as $v=>$l):?><option value="<?=$v?>" <?=$p['status_produk']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select><label>WhatsApp</label><input class="form-control mb-3" name="whatsapp" value="<?=e($p['whatsapp']??'')?>"><label>Gambar (max 3MB)</label><input type="file" class="form-control mb-3" name="gambar_produk" accept="image/*"><?php if($p['gambar_produk']):?><img src="<?=e($p['gambar_produk'])?>" style="max-width:160px" class="mb-3"><?php endif;?><button class="btn btn-green">Simpan</button><a href="my-products.php" class="btn btn-secondary">Kembali</a></form></div><?php footpage();